const {realVar, vectorVar, vec} = Symbolic;
const {fitDataAsync} = DataScience;
const trainXs = NArray.range(0, 500).map(() => [2 * Math.random() - 1, 2 * Math.random() - 1]);
const testXs = NArray.range(0, 2000).map(() => [2 * Math.random() - 1, 2 * Math.random() - 1]);
const yf = ([x, y]) => 2 * x * x - y * y + x * y + 0.5 + 0.3 * (2 * Math.random() - 1);

const plot = IO.plotPointCloud(trainXs.map(([x, y]) => [x, y, yf([x, y])]));
const surface = plot.add([], {color: [0, 0, 1]});

const x = realVar("x", true);
const y = realVar("y", true);
const a = vectorVar("a", 6);
const f = vec(1, x, y, x.mul(x), x.mul(y), y.mul(y)).dot(a);

const updateSurface = (compiledModel, theta) => {
    surface.update(testXs.map(([x, y]) => [x, y, compiledModel({x, y, ...theta})]));
    plot.render();
};

setTimeout(async () => {
    const {compiledModel, theta} = await fitDataAsync(trainXs, trainXs.map(yf), f, {
        epochs: 10000,
        batch: 20,
        continuationEvery: 100,
        continuationFn: ({compiledModel, theta}) => updateSurface(compiledModel, theta),
    });
    updateSurface(compiledModel, theta);
});
plot;
